Pika.Archive2=function(){return{loadExploreMore:function(nid){$.getJSON("/Archive2/AJAX?method=getExploreMoreContent&id="+encodeURIComponent(nid),function(data){if(data.success){$("#explore-more-body").html(data.exploreMore);Pika.initCarousels("#explore-more-body .panel-collapse.in .jcarousel")}}).fail(Pika.ajaxFail)},loadRelatedObjects:function(personName){$.getJSON("/Archive2/AJAX?method=getRelatedObjectsForPerson&name="+encodeURIComponent(personName),function(data){if(data.success&&data.hasResults){$("#personRelatedObjectsContent").html(data.html)}else{$("#personRelatedObjectsPanel").hide()}}).fail(Pika.ajaxFail)}}}();